  currentItem = (currentItem + 1) % 4;

  showUser();
});
prevBtn.addEventListener("click", () => {
  currentItem = (currentItem - 1 + 4) % 4;
  showUser();
});
randomBtn.addEventListener("click", () => {
  currentItem = Math.floor(Math.random() * reviews.length);
  console.log(currentItem);
  showUser();
});

